def helper_update_stage(ctx, nb):
    obs = ctx.get('observation', '')
    inv = ctx.get('world', {}).get('inventory', [])
    task = ctx.get('task', {})
    target_type = task.get('target_type', '')
    destination_type = task.get('destination_type', '')
    action = ctx.get('action', {}).get('raw', '')
    if not obs:
        return
    if action == nb.get('last_action') and obs == nb.get('last_observation'):
        nb['repeated_count'] = nb.get('repeated_count', 0) + 1
    else:
        nb['repeated_count'] = 0
    nb['last_action'] = action
    nb['last_observation'] = obs
    if nb['stage'] == 'find_target':
        if target_type and target_type in inv:
            nb['stage'] = 'transform'
            nb['target_found'] = True
        elif 'take ' + target_type in action and 'from' in action:
            nb['stage'] = 'take_target'
    elif nb['stage'] == 'take_target':
        if target_type and target_type in inv:
            nb['stage'] = 'transform'
            nb['target_found'] = True
    elif nb['stage'] == 'transform':
        if 'cool' in action or 'heat' in action or 'clean' in action:
            nb['stage'] = 'go_destination'
        elif destination_type and destination_type in obs and 'put' in action:
            nb['stage'] = 'put_target'
    elif nb['stage'] == 'go_destination':
        if 'put' in action and destination_type in action:
            nb['stage'] = 'put_target'
    elif nb['stage'] == 'put_target':
        if 'put' in action and destination_type in action:
            nb['stage'] = 'done'
    if nb['repeated_count'] >= 3 and nb['stage'] != nb.get('last_hint_stage'):
        return {'kind': 'inject_hint', 'message': 'You seem stuck. Try looking around or checking inventory to find the ' + target_type + '. Then take it, transform it if needed, and put it in the ' + destination_type + '.'}
        nb['last_hint_stage'] = nb['stage']
    return None

def hook(ctx, nb):
    try:
        return helper_update_stage(ctx, nb)
    except Exception:
        return None

def hook(ctx, nb):
    try:
        stage = nb.get('stage', 'find_target')
        task = ctx.get('task', {})
        target_type = task.get('target_type', 'object')
        destination_type = task.get('destination_type', 'container')
        if stage == 'find_target':
            return {'message': 'Look for the ' + target_type + '. Explore cabinets and containers.'}
        elif stage == 'take_target':
            return {'message': 'Take the ' + target_type + ' when you find it.'}
        elif stage == 'transform':
            return {'message': 'Apply the required transformation (cool, heat, clean) to the ' + target_type + '.'}
        elif stage == 'go_destination':
            return {'message': 'Go to the ' + destination_type + ' to place the ' + target_type + '.'}
        elif stage == 'put_target':
            return {'message': 'Put the ' + target_type + ' in the ' + destination_type + '.'}
        return None
    except Exception:
        return None
